ent-c58ebf36c1dd51040dd9bc62b3edf3de	default	植物プランクトン	植物プランクトン\n赤潮生物に含まれる、クラゲ類よりも小型のプランクトン。<SEP>渦鞭毛藻類など、赤潮を引き起こすことがある小型のプランクトン。<SEP>Dimethyl Sulfide (DMS)を放出する源の一つ。<SEP>磯のかおりとして知られるジメチルスルフィド (DMS)を放出する生物の一種。<SEP>赤潮生物として一般的なプランクトンの一種。	[0.012147178,-0.027485332,-0.020732816,-0.08398568,0.017547077,0.009646685,-0.00013324739,0.008242104,0.028603291,0.005901684,-0.021735316,-0.008680712,0.015169374,-0.011085077,0.13138022,0.015077514,0.015586533,-0.016996682,0.0074562635,-0.0078036836,0.009576493,-0.009468774,0.012533311,-0.015917681,-0.0040200455,-0.028827127,0.025238257,-0.02250812,0.029473905,-0.008355992,-0.021594286,0.0058986614,0.01808831,-0.00740229,0.036320504,0.021444494,0.032491125,-0.009804935,0.009618288,0.019030327,-0.04388953,0.015958518,0.007669224,0.020597896,0.023782592,0.014966909,0.015758652,-0.022456195,0.030756932,0.027603611,0.00071423454,-0.009743196,-0.018328259,-0.1811384,-0.0022037895,0.03607032,-0.0013273928,-0.015641043,0.013263162,-0.0132945245,-0.0067810277,-0.0050877174,-0.0049253763,-0.032976612,0.023665337,-0.0248658,0.009371516,0.019242281,-0.004701217,0.000149182,-0.004569311,-0.010682159,-0.007824789,-0.0033103013,0.008686545,-0.0064173685,0.020709949,-0.038637616,0.017474826,0.029740727,0.03505232,-0.024252363,-0.009720693,-0.014652376,-0.005472163,0.012755104,-0.032403,-0.046391703,-0.0011949254,0.02697788,0.017751122,0.00585908,0.027317911,-0.015687766,-0.014811703,0.0367139,-0.010040903,-0.02408606,-0.012136301,-0.022576727,-0.025632838,0.025383841,-0.029670529,0.024945417,0.007195452,-0.005189878,0.004118388,0.010423123,-0.028121645,0.0055265287,0.009956052,-0.007112574,0.008115448,0.021652078,0.0025865096,-0.12236825,0.026169566,0.0011058511,-0.023017474,-0.004729809,-0.003624237,-0.01400263,0.018255042,0.015058417,-0.012484282,-0.010126167,-0.0016106911,-0.012851689,0.0071402136,-0.0039889165,0.016439848,-0.004814839,-0.022033397,-0.0037958168,-0.002084255,0.007344584,-0.036949888,-0.021620147,0.002156331,-0.009794428,-0.008633