ent-a190d2df8ff181f7d96a0225c498b361	default	ゼラチン質プランクトン季節出現要旨(2003)	ゼラチン質プランクトン季節出現要旨(2003)\n上野俊士郎、河原正人、小林亜玲、河村真理子、久保田信による、山口県響灘沿岸域におけるゼラチン質プランクトンの季節的出現に関する講演要旨。2003年度日本海洋学会秋季大会講演要旨集に掲載。	[0.018299699,-0.022115003,0.0038218943,-0.054413985,0.009671052,0.01757133,0.005608127,0.002249235,0.0033202362,0.026179712,-0.010020713,-0.0032713946,-0.0012202644,0.0059063984,0.13665509,0.012473345,0.006785617,-0.0065955874,0.015435842,-0.020894982,0.023272308,-0.026783518,-0.0017817634,-0.01611596,-0.020798707,-0.007454306,0.016220376,0.004084965,0.04505048,0.018414184,0.033402007,0.037463926,0.021317314,0.001466575,0.02487886,0.015511836,0.005870746,-0.016165892,0.022532754,-0.005642887,-0.012041059,0.011236431,-0.014350779,0.0037979558,0.005299416,-0.0019829643,-0.015038361,-0.013741941,0.029715307,0.0324287,-0.0061846026,-0.0066269753,-0.008740204,-0.18668434,7.858587e-05,0.0023073116,-0.029146243,-0.024376228,0.020997385,0.007978706,-0.006888568,-0.00546774,-0.008030551,-0.015923869,-0.0055834283,0.0018011758,0.0057524233,0.029640041,-0.016272899,-0.022573844,-0.023553466,0.013814481,0.008906834,-0.014074636,0.01581453,-0.011404321,0.0071044806,0.0059581543,0.008104152,0.032587096,0.024943184,0.0018795253,-0.014025981,-0.012046417,-0.011171745,-0.0065222173,0.005919001,-0.036528092,-0.0018119646,0.05974462,0.004412929,0.03161292,0.00054757105,0.01597172,-0.0066030053,0.0072346097,0.003763772,-0.02176609,-0.00439068,-0.021829544,-0.008054006,0.0015912238,-0.012430412,0.02526533,0.00058601506,0.0028384756,0.0085861,0.013202446,-0.011800101,0.023612611,-0.019769788,0.0039745555,-0.007695007,0.010804746,-0.024364015,-0.12609375,-0.022385465,-0.0037112092,-0.02759811,0.022988044,-0.0090510575,0.0059049996,-0.010569882,0.018019449,-0.018641293,-0.0030924492,0.0070968852,-0.023522383,0.009072041,-0.010301922,0.006209536,0.0042997627,0.021642858,0.021045366,0.007873458,0.00236503,-0.010192928,-0.019525917,0.012040548,-0.018596543,-0.020421552,0.020378327,-0.0018893969,-0.008246791,